using System.Collections;
using System.Collections.Generic;
using System.Linq;
using Astrea.RunModifiers;
using DG.Tweening;
using LittleLeo;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class ModifiersPanel : MonoBehaviour
{
	public enum StateEnum
	{
		Modifiers,
		Buttons
	}

	[Header("Components")]
	[SerializeField]
	private Canvas canvas;

	[SerializeField]
	private RectTransform contentTransform;

	[SerializeField]
	private Scrollbar activeScrollbar;

	[SerializeField]
	private GameObject modifierHorizontalLayoutPrefab;

	[SerializeField]
	private GridLayoutGroup gridLayoutGroup;

	[SerializeField]
	private RectTransform scrollRectBaseRectTransform;

	[SerializeField]
	private Image scrollbarImage;

	[Header("ForceRebuild")]
	[SerializeField]
	protected RectTransform rectTransformParent;

	[Header("Select Modifiers")]
	[SerializeField]
	private RectTransform selectedModifiersHorizontalLayout;

	[SerializeField]
	private GridLayoutGroup selectedModifiersContentGridLayoutGroup;

	[SerializeField]
	private GameObject modifierLevelIconModifiersPanelPrefab;

	[Header("Buttons")]
	[SerializeField]
	protected Button randomSelectionButton;

	[SerializeField]
	protected Button clearModifiersButton;

	[SerializeField]
	protected Button backButton;

	[Header("ModifiersPanelBattleScene")]
	[SerializeField]
	private bool isBattleScene;

	[Header("Buttons")]
	[SerializeField]
	private float scrollRectHeightModifier = 40f;

	private const float SCROLL_SPEED_DURATION = 0.15f;

	private const float MODIFIER_HEIGHT_DEFAULT = 53f;

	protected bool isOnModifierPanel;

	protected RunModifiersHandler runModifiersHandler;

	protected List<ModifierLevelIconModifiersPanel> selectedModifiersList = new List<ModifierLevelIconModifiersPanel>();

	protected List<List<ModifierHorizontalLayout>> modifierHorizontalLayoutListList = new List<List<ModifierHorizontalLayout>>();

	protected List<ZoomableInstance> buttonsZoomableInstancesList = new List<ZoomableInstance>();

	protected StateEnum currentState;

	protected int currentModifierLineIndex;

	protected int currentModifierElementIndex;

	protected int currentButtonIndex;

	protected Tweener tweenerNavigation;

	protected ZoomableInstance currentZoomableInstance;

	protected SaveSystem saveSystem;

	protected int selectedModifiersConstraint;

	protected float scrollRectBaseOriginalHeight;

	protected float scrollbarImageOriginalHeight;

	public static ModifiersPanel Instance;

	protected InputManager inputManager => ReferenceSingleton<InputManager>.Instance;

	public List<ModifierLevelIconModifiersPanel> SelectedModifiersList => selectedModifiersList;

	private void Awake()
	{
		Instance = this;
		selectedModifiersConstraint = selectedModifiersContentGridLayoutGroup.constraintCount + 1;
		scrollRectBaseOriginalHeight = scrollRectBaseRectTransform.sizeDelta.y;
		scrollbarImageOriginalHeight = scrollbarImage.rectTransform.sizeDelta.y;
	}

	private void Start()
	{
		saveSystem = ReferenceSingleton<AssetsReference>.Instance.SaveSystem;
		runModifiersHandler = ReferenceSingleton<AssetsReference>.Instance.DailyRunHandler.RunModifiersHandler;
		buttonsZoomableInstancesList.Add(randomSelectionButton.GetComponent<ZoomableInstance>());
		buttonsZoomableInstancesList.Add(clearModifiersButton.GetComponent<ZoomableInstance>());
		if (!isBattleScene)
		{
			StartCoroutine(WaitnUtilLocalizationTableIsLoaded());
		}
	}

	private IEnumerator WaitnUtilLocalizationTableIsLoaded()
	{
		yield return new WaitUntil(() => (bool)ReferenceSingleton<LocalizationManager>.Instance && ReferenceSingleton<LocalizationManager>.Instance.LocalizationTableLoaded);
		Populate();
	}

	private void Update()
	{
		if (!inputManager.IsPaused && inputManager.IsJoystickBeingUsed && isOnModifierPanel)
		{
			bool verticalAxisUp = inputManager.GetVerticalAxisUp();
			bool verticalAxisDown = inputManager.GetVerticalAxisDown();
			bool horizontalAxisRight = inputManager.GetHorizontalAxisRight();
			bool horizontalAxisLeft = inputManager.GetHorizontalAxisLeft();
			bool selectButtonUp = inputManager.GetSelectButtonUp();
			bool cancelButtonUp = inputManager.GetCancelButtonUp();
			switch (currentState)
			{
			case StateEnum.Modifiers:
				UpdateModifiers(verticalAxisUp, verticalAxisDown, horizontalAxisRight, horizontalAxisLeft, selectButtonUp, cancelButtonUp);
				break;
			case StateEnum.Buttons:
				UpdateButtons(verticalAxisUp, verticalAxisDown, horizontalAxisRight, horizontalAxisLeft, selectButtonUp, cancelButtonUp);
				break;
			}
		}
	}

	private void UpdateButtons(bool up, bool down, bool right, bool left, bool select, bool cancel)
	{
		if (up)
		{
			buttonsZoomableInstancesList[currentButtonIndex].OnMouseExit();
			ChangeState(StateEnum.Modifiers);
		}
		else
		{
			if (down)
			{
				return;
			}
			if (right)
			{
				buttonsZoomableInstancesList[currentButtonIndex].OnMouseExit();
				currentButtonIndex++;
				if (currentButtonIndex >= buttonsZoomableInstancesList.Count)
				{
					currentButtonIndex = buttonsZoomableInstancesList.Count - 1;
				}
				buttonsZoomableInstancesList[currentButtonIndex].OnMouseOver();
			}
			else if (left)
			{
				buttonsZoomableInstancesList[currentButtonIndex].OnMouseExit();
				currentButtonIndex--;
				if (currentButtonIndex < 0)
				{
					currentButtonIndex = 0;
				}
				buttonsZoomableInstancesList[currentButtonIndex].OnMouseOver();
			}
			else if (select)
			{
				buttonsZoomableInstancesList[currentButtonIndex].GetComponent<Button>().onClick.Invoke();
			}
			else if (cancel)
			{
				buttonsZoomableInstancesList[currentButtonIndex].OnMouseExit();
				backButton.onClick.Invoke();
			}
		}
	}

	private void UpdateModifiers(bool up, bool down, bool right, bool left, bool select, bool cancel)
	{
		if (up)
		{
			currentZoomableInstance.OnMouseExit();
			currentModifierLineIndex--;
			if (currentModifierLineIndex < 0)
			{
				currentModifierLineIndex = 0;
			}
			currentZoomableInstance = GetCurrentModifierZoomable();
			ChangeModifierActiveScrollBarValue();
		}
		else if (down)
		{
			currentZoomableInstance.OnMouseExit();
			currentModifierLineIndex++;
			if (currentModifierLineIndex >= modifierHorizontalLayoutListList.Count)
			{
				currentModifierLineIndex = modifierHorizontalLayoutListList.Count - 1;
				if (!isBattleScene)
				{
					ChangeState(StateEnum.Buttons);
					return;
				}
			}
			if (currentModifierElementIndex >= modifierHorizontalLayoutListList[currentModifierLineIndex].Count)
			{
				currentModifierElementIndex = modifierHorizontalLayoutListList[currentModifierLineIndex].Count - 1;
			}
			currentZoomableInstance = GetCurrentModifierZoomable();
			ChangeModifierActiveScrollBarValue();
		}
		else if (right)
		{
			currentZoomableInstance.OnMouseExit();
			currentModifierElementIndex++;
			if (currentModifierElementIndex >= modifierHorizontalLayoutListList[currentModifierLineIndex].Count)
			{
				currentModifierElementIndex = modifierHorizontalLayoutListList[currentModifierLineIndex].Count - 1;
			}
			currentZoomableInstance = GetCurrentModifierZoomable();
			currentZoomableInstance.OnMouseOver();
		}
		else if (left)
		{
			currentZoomableInstance.OnMouseExit();
			currentModifierElementIndex--;
			if (currentModifierElementIndex < 0)
			{
				currentModifierElementIndex = 0;
			}
			currentZoomableInstance = GetCurrentModifierZoomable();
			currentZoomableInstance.OnMouseOver();
		}
		else if (select && !isBattleScene)
		{
			modifierHorizontalLayoutListList[currentModifierLineIndex][currentModifierElementIndex].Select();
		}
		else if (cancel)
		{
			modifierHorizontalLayoutListList[currentModifierLineIndex][currentModifierElementIndex].OnMouseExit();
			backButton.onClick.Invoke();
		}
	}

	private ZoomableInstance GetCurrentModifierZoomable()
	{
		if (isBattleScene)
		{
			return modifierHorizontalLayoutListList[currentModifierLineIndex][currentModifierElementIndex].GetIconImageZoomableInstance();
		}
		return modifierHorizontalLayoutListList[currentModifierLineIndex][currentModifierElementIndex].GetToggleZoomableInstance();
	}

	protected void ChangeState(StateEnum newState)
	{
		switch (newState)
		{
		case StateEnum.Modifiers:
			currentZoomableInstance = GetCurrentModifierZoomable();
			break;
		case StateEnum.Buttons:
			currentZoomableInstance = buttonsZoomableInstancesList[currentButtonIndex];
			break;
		}
		currentZoomableInstance.OnMouseOver();
		currentState = newState;
	}

	protected void Populate()
	{
		selectedModifiersList.Clear();
		modifierHorizontalLayoutListList.Clear();
		Store();
		int constraintCount = gridLayoutGroup.constraintCount;
		List<RunModifier> list = new List<RunModifier>();
		if (isBattleScene)
		{
			for (int i = 0; i < runModifiersHandler.ActiveRunModifiers.Count; i++)
			{
				list.Add(runModifiersHandler.ActiveRunModifiers[i]);
			}
		}
		else
		{
			for (int j = 0; j < runModifiersHandler.AllRunModifiersList.Count; j++)
			{
				if (!runModifiersHandler.AllRunModifiersList[j].DailyRunOnly)
				{
					list.Add(runModifiersHandler.AllRunModifiersList[j]);
				}
			}
		}
		list = list.OrderBy((RunModifier _) => (int)_.RunModifierType).ToList();
		int num = 0;
		int num2 = 0;
		modifierHorizontalLayoutListList.Add(new List<ModifierHorizontalLayout>());
		for (int k = 0; k < list.Count; k++)
		{
			if (num == constraintCount)
			{
				modifierHorizontalLayoutListList.Add(new List<ModifierHorizontalLayout>());
				num2++;
				num = 0;
			}
			ModifierHorizontalLayout component = ReferenceSingleton<PoolHandler>.Instance.GetObject(modifierHorizontalLayoutPrefab.name, contentTransform).GetComponent<ModifierHorizontalLayout>();
			if (isBattleScene)
			{
				component.Populate(list[k]);
			}
			else
			{
				component.Populate(list[k], enableToggle: true);
			}
			modifierHorizontalLayoutListList[num2].Add(component);
			num++;
		}
	}

	private void Store()
	{
		int childCount = contentTransform.childCount;
		for (int i = 0; i < childCount; i++)
		{
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(contentTransform.GetChild(0).gameObject);
		}
	}

	protected void ChangeModifierActiveScrollBarValue()
	{
		float newScrollValue = 1f - (float)currentModifierLineIndex / (float)(modifierHorizontalLayoutListList.Count - 1);
		if (tweenerNavigation != null)
		{
			tweenerNavigation.Kill();
			tweenerNavigation = null;
		}
		tweenerNavigation = DOTween.To(() => activeScrollbar.value, delegate(float x)
		{
			activeScrollbar.value = x;
		}, newScrollValue, 0.15f).OnComplete(delegate
		{
			activeScrollbar.value = newScrollValue;
			currentZoomableInstance.OnMouseOver();
			tweenerNavigation = null;
		});
	}

	public void AddModifier(RunModifier runModifier)
	{
		ModifierLevelIconModifiersPanel component = ReferenceSingleton<PoolHandler>.Instance.GetObject(modifierLevelIconModifiersPanelPrefab.name, selectedModifiersContentGridLayoutGroup.transform).GetComponent<ModifierLevelIconModifiersPanel>();
		component.Initialize(runModifier);
		List<RunModifier> runModifiersToMute = runModifier.RunModifiersToMute;
		for (int i = 0; i < runModifiersToMute.Count; i++)
		{
			RunModifier muteModifier = runModifiersToMute[i];
			ModifierHorizontalLayout modifierHorizontalLayout = null;
			for (int j = 0; j < modifierHorizontalLayoutListList.Count; j++)
			{
				modifierHorizontalLayout = modifierHorizontalLayoutListList[j].Find((ModifierHorizontalLayout _) => _.RunModifier == muteModifier);
				if (modifierHorizontalLayout != null)
				{
					break;
				}
			}
			modifierHorizontalLayout.Disable();
			RunModifier runModifier2 = (from _ in selectedModifiersList
				where _.GetRunModifier() == muteModifier
				select _.GetRunModifier()).FirstOrDefault();
			if (runModifier2 != null)
			{
				RemoveModifier(runModifier2);
			}
		}
		VerifyLayout();
		selectedModifiersList.Add(component);
	}

	private void VerifyLayout()
	{
		int num = selectedModifiersContentGridLayoutGroup.transform.childCount / selectedModifiersConstraint;
		float num2 = 0f;
		float num3 = 0f;
		if (num == 0)
		{
			num2 = -26.5f;
		}
		else
		{
			num2 = (float)num * 53f;
			num3 = (float)num * (53f + scrollRectHeightModifier);
		}
		float y = num2 + 53f;
		selectedModifiersHorizontalLayout.sizeDelta = new Vector2(selectedModifiersHorizontalLayout.sizeDelta.x, y);
		float y2 = scrollRectBaseOriginalHeight - num3;
		scrollRectBaseRectTransform.sizeDelta = new Vector2(scrollRectBaseRectTransform.sizeDelta.x, y2);
		float y3 = scrollRectBaseOriginalHeight - num2;
		scrollbarImage.rectTransform.sizeDelta = new Vector2(scrollbarImage.rectTransform.sizeDelta.x, y3);
		LayoutRebuilder.ForceRebuildLayoutImmediate(rectTransformParent);
	}

	public void RemoveModifier(RunModifier runModifier, bool needsVerifyLayout = false)
	{
		ModifierLevelIconModifiersPanel modifierLevelIconModifiersPanel = selectedModifiersList.Find((ModifierLevelIconModifiersPanel _) => _.GetRunModifier() == runModifier);
		if (modifierLevelIconModifiersPanel != null)
		{
			selectedModifiersList.Remove(modifierLevelIconModifiersPanel);
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(modifierLevelIconModifiersPanel.gameObject);
		}
		List<RunModifier> runModifiersToMute2 = runModifier.RunModifiersToMute;
		for (int i = 0; i < runModifiersToMute2.Count; i++)
		{
			RunModifier runModifiersToMute = runModifiersToMute2[i];
			for (int j = 0; j < modifierHorizontalLayoutListList.Count; j++)
			{
				ModifierHorizontalLayout modifierHorizontalLayout = modifierHorizontalLayoutListList[j].Find((ModifierHorizontalLayout _) => _.RunModifier == runModifiersToMute);
				if (modifierHorizontalLayout != null)
				{
					modifierHorizontalLayout.Enable();
					break;
				}
			}
		}
		if (needsVerifyLayout)
		{
			VerifyLayout();
		}
	}

	private void SaveModifiers()
	{
		List<RunModifier> list = new List<RunModifier>();
		for (int i = 0; i < selectedModifiersList.Count; i++)
		{
			RunModifier runModifier = selectedModifiersList[i].GetRunModifier();
			list.Add(runModifier);
		}
		list = list.OrderBy((RunModifier _) => (int)_.RunModifierType).ToList();
		List<string> list2 = new List<string>();
		for (int j = 0; j < list.Count; j++)
		{
			list2.Add(list[j].name);
		}
		saveSystem.SaveModifiersRunCustomization(list2, ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName);
	}

	private void LoadModifiers()
	{
		string characterName = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName;
		if (!saveSystem.HasModifiersRunCustomizationSaveKey(characterName))
		{
			return;
		}
		List<string> list = saveSystem.LoadModifiersRunCustomization(characterName);
		for (int i = 0; i < list.Count; i++)
		{
			RunModifier modifier = runModifiersHandler.GetRunModifier(list[i]);
			if (!(modifier != null))
			{
				continue;
			}
			AddModifier(modifier);
			for (int j = 0; j < modifierHorizontalLayoutListList.Count; j++)
			{
				ModifierHorizontalLayout modifierHorizontalLayout = modifierHorizontalLayoutListList[j].Find((ModifierHorizontalLayout _) => _.RunModifier == modifier);
				if (modifierHorizontalLayout != null)
				{
					modifierHorizontalLayout.SetToggleIsOnWithoutNotify(value: true);
				}
			}
		}
	}

	private void CleanAllModifiers()
	{
		int childCount = selectedModifiersContentGridLayoutGroup.transform.childCount;
		for (int i = 0; i < childCount; i++)
		{
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(selectedModifiersContentGridLayoutGroup.transform.GetChild(0).gameObject);
		}
		for (int j = 0; j < modifierHorizontalLayoutListList.Count; j++)
		{
			List<ModifierHorizontalLayout> list = modifierHorizontalLayoutListList[j];
			for (int k = 0; k < list.Count; k++)
			{
				list[k].Reset();
			}
		}
		selectedModifiersList.Clear();
		VerifyLayout();
	}

	public List<RunModifier> GetRunCustomizationActiveRunModifiers()
	{
		List<RunModifier> list = new List<RunModifier>();
		for (int i = 0; i < SelectedModifiersList.Count; i++)
		{
			list.Add(SelectedModifiersList[i].GetRunModifier());
		}
		return list;
	}

	public virtual void OnShowModifiersPanel()
	{
		canvas.enabled = true;
		InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
		{
			isOnModifierPanel = true;
		});
		CleanAllModifiers();
		LoadModifiers();
		VerifyLayout();
		if (inputManager.IsJoystickBeingUsed)
		{
			currentModifierElementIndex = 0;
			currentModifierLineIndex = 0;
			ChangeState(StateEnum.Modifiers);
			ChangeModifierActiveScrollBarValue();
		}
	}

	public virtual void OnHideModifiersPanel()
	{
		canvas.enabled = false;
		isOnModifierPanel = false;
		SaveModifiers();
		if (inputManager.IsJoystickBeingUsed && currentZoomableInstance != null)
		{
			currentZoomableInstance.OnMouseExit();
		}
	}

	public void OnInputChangedToMouseToggleObjects(bool value)
	{
		if (isOnModifierPanel)
		{
			if (currentZoomableInstance != null)
			{
				currentZoomableInstance.OnMouseExit();
			}
			if (inputManager.IsJoystickBeingUsed)
			{
				currentModifierElementIndex = 0;
				currentModifierLineIndex = 0;
				ChangeState(StateEnum.Modifiers);
				ChangeModifierActiveScrollBarValue();
			}
		}
	}

	public void OnRandomSelectionButtonPressed()
	{
		OnClearModifiersButtonPressed();
		List<RunModifier> randomizedRunModifiers = runModifiersHandler.GetRandomizedRunModifiers(dailyRun: false);
		for (int i = 0; i < randomizedRunModifiers.Count; i++)
		{
			RunModifier modifier = randomizedRunModifiers[i];
			modifierHorizontalLayoutListList.ForEach(delegate(List<ModifierHorizontalLayout> _)
			{
				(from _ in _
					where _.RunModifier == modifier
					select (_)).FirstOrDefault()?.SetToggleIsOnWithoutNotify(value: true);
			});
		}
		for (int j = 0; j < randomizedRunModifiers.Count; j++)
		{
			AddModifier(randomizedRunModifiers[j]);
		}
	}

	public void OnClearModifiersButtonPressed()
	{
		CleanAllModifiers();
	}

	public void OnLanguageChanged()
	{
		for (int i = 0; i < modifierHorizontalLayoutListList.Count; i++)
		{
			List<ModifierHorizontalLayout> list = modifierHorizontalLayoutListList[i];
			for (int j = 0; j < list.Count; j++)
			{
				list[j].PopulateText();
			}
		}
	}
}
